const note = { text: "Call Ben" };

Object.defineProperty(note, "draft", { value: true, writable: true });
Object.defineProperty(note, "text", { enumerable: false });
note.pinned = false;

console.log(Object.keys(note).join(","));
console.log(note.draft, "text" in note);
console.log(JSON.stringify(note));
console.log(Object.getOwnPropertyNames(note).length);
